import { MeshBasicNodeMaterial } from 'three/webgpu';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Color } = ctx.THREE;
  const root = new Group();
  root.name = config.name || 'collection-card-1';
  root.userData.handlers = {};

  const width = 2.56;
  const height = 1.6;
  const createdResources = [];
  const loadedTextures = [];

  const backingGeometry = new PlaneGeometry(width, height);
  const backingMaterial = new MeshBasicNodeMaterial({
    color: '#0b0b10',
    transparent: true,
    opacity: 0.98
  });
  const backing = new Mesh(backingGeometry, backingMaterial);
  backing.position.z = -0.045;
  backing.renderOrder = 0;
  root.add(backing);
  createdResources.push(backingGeometry, backingMaterial);

  const imageGeometry = new PlaneGeometry(width, height);
  const imageMaterial = new MeshBasicNodeMaterial({
    color: '#e8ecf2',
    transparent: true,
    opacity: 0.92
  });
  const imagePlane = new Mesh(imageGeometry, imageMaterial);
  imagePlane.position.z = 0;
  imagePlane.renderOrder = 1;
  root.add(imagePlane);
  createdResources.push(imageGeometry, imageMaterial);

  const stripeGeometry = new PlaneGeometry(0.035, 1.16);
  const stripeMaterial = new MeshBasicNodeMaterial({
    color: '#ff2a38'
  });
  const stripe = new Mesh(stripeGeometry, stripeMaterial);
  stripe.position.set(-1.08, 0, 0.025);
  stripe.renderOrder = 2;
  root.add(stripe);
  createdResources.push(stripeGeometry, stripeMaterial);

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of items) {
    const content = typeof item.text === 'string' ? item.text : '';
    const typography = item.typography || {};
    const textObject = ctx.fontAtlas.createText(content, {
      fontSize: typography.fontSize ?? 39,
      color: '#e8ecf2',
      align: 'left',
      letterSpacingPx: 1
    });

    textObject.position.set(-0.88, -0.06, 0.04);
    textObject.renderOrder = 3;
    root.add(textObject);
  }

  const billboard = (renderer, scene, camera) => {
    if (camera && camera.quaternion) {
      root.quaternion.copy(camera.quaternion);
    }
  };
  imagePlane.onBeforeRender = billboard;

  const textureUrl = config.imageUrl;
  if (textureUrl) {
    ctx.textureLoader.loadTexture(textureUrl).then((texture) => {
      if (!texture || !root.parent && root.userData.cleaned) {
        return;
      }

      const image = texture.image;
      const imageWidth = image?.width || 512;
      const imageHeight = image?.height || 320;
      const source = config.atlasRegion || {
        x: 0,
        y: 0,
        width: 512,
        height: 320
      };

      texture.wrapS = ctx.THREE.ClampToEdgeWrapping;
      texture.wrapT = ctx.THREE.ClampToEdgeWrapping;
      texture.repeat.set(
        source.width / imageWidth,
        source.height / imageHeight
      );
      texture.offset.set(
        source.x / imageWidth,
        1 - (source.y + source.height) / imageHeight
      );
      texture.needsUpdate = true;

      imageMaterial.map = texture;
      imageMaterial.color = new Color('#e8ecf2');
      imageMaterial.needsUpdate = true;
      loadedTextures.push(texture);
    }).catch(() => {});
  }

  root.userData.cleanup = () => {
    if (root.userData.cleaned) return;
    root.userData.cleaned = true;

    root.traverse((object) => {
      if (object.geometry && !createdResources.includes(object.geometry)) {
        object.geometry.dispose?.();
      }

      const material = object.material;
      if (material && !createdResources.includes(material)) {
        if (Array.isArray(material)) {
          material.forEach((entry) => entry.dispose?.());
        } else {
          material.dispose?.();
        }
      }
    });

    for (const resource of createdResources) {
      resource.dispose?.();
    }

    for (const texture of loadedTextures) {
      texture.dispose?.();
    }

    root.clear();
  };

  return root;
}
